import re, zlib
data = open('extrato_maio_2026.pdf','rb').read()
streams = re.findall(rb'stream\r?\n(.*?)endstream', data, re.S)
txt = b''
for s in streams:
    try: txt += zlib.decompress(s.strip(b'\r\n'))
    except Exception: pass
# map glyph codes -> chars per observed encoding
spec = {0x0003:' ',0x000f:',',0x0011:'.',0x0012:'/',0x07df:'—',0x07e0:'—'}
out=[]
for m in re.finditer(rb'\[(.*?)\]\s*TJ', txt, re.S):
    parts = re.findall(rb'\((-?\d+)\)', m.group(1))
    s=''
    for p in parts:
        v=int(p)
        if v in spec: s+=spec[v]
        elif 0x13<=v<=0x1c: s+=chr(ord('0')+v-0x13)
        elif v==0: pass
        else: s+=chr(v+0x1D)
    out.append(s)
print('\n'.join(out))
